	"service.",
] as const;
const TELEMETRY_ENABLED = process.env.HEVY_MCP_TELEMETRY !== "0";
const DIAGNOSTIC_DETAILS_ENABLED =
	process.env.HEVY_MCP_TELEMETRY_DIAGNOSTICS !== "0";

function isObject(value: unknown): value is object {
	return typeof value === "object" && value !== null;
}

function truncate(value: string, length: number): string {
	return value.length > length ? `${value.slice(0, length - 1)}…` : value;
}

function escapeRegExp(value: string): string {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function removeHomePath(value: string): string {
	const home = process.env.HOME?.trim();
	const withConfiguredHome = home
		? value.replace(new RegExp(escapeRegExp(home), "g"), "~")
		: value;
	return withConfiguredHome.replace(/\/(?:Users|home)\/[^/\s]+/g, "~");
}

const EMAIL = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi;

function removeControlCharacters(value: string): string {
	let output = "";
	let inEscapeSequence = false;
	for (const character of value) {
		const codePoint = character.codePointAt(0) ?? 0;
		if (inEscapeSequence) {
			if (codePoint >= 0x40 && codePoint <= 0x7e) {
				inEscapeSequence = false;
			}
			continue;
		}
		if (codePoint === 0x1b) {
			inEscapeSequence = true;
			continue;
		}
		if (
			codePoint <= 0x1f &&
			codePoint !== 0x09 &&
			codePoint !== 0x0a &&
			codePoint !== 0x0d
		) {
			continue;
		}
		if (codePoint === 0x7f) continue;
		output += character;
	}
	return output;
}

/** Remove common credentials and URL payloads without inspecting object fields. */
export function sanitizeDiagnosticText(
	value: string,
	maxLength = MAX_MESSAGE_LENGTH,
): string {
	const withoutControlCharacters = removeControlCharacters(value);
	const withoutSecrets = withoutControlCharacters
		.replace(/\bBearer\s+[^\s,;]+/gi, "Bearer [REDACTED]")
		.replace(
			/\b(api[-_ ]?key|authorization|password|secret|token)\s*[:=]\s*(?:"[^"]*"|'[^']*'|[^\s,;]+)/gi,
			"$1=[REDACTED]",
		)
		.replace(EMAIL, "[EMAIL_REDACTED]")
		.replace(/\bhttps?:\/\/[^\s)<>]+/gi, "[URL]");
	return truncate(removeHomePath(withoutSecrets).trim(), maxLength);
}

function sanitizeAttributeValue(
	_key: string,
	value: TelemetryAttributeValue,
): TelemetryAttributeValue {
	if (typeof value !== "string") return value;
	return sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH);
}

function copyAttributes(
	attributes: TelemetryAttributes | undefined,
): TelemetryAttributes {
	if (!attributes) return {};
	const output: TelemetryAttributes = {};
	for (const [rawKey, rawValue] of Object.entries(attributes)) {
		const key = truncate(rawKey, 128);
		if (
			!key ||
			!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix)) ||
			(typeof rawValue === "number" && !Number.isFinite(rawValue))
		) {
			continue;
		}
		output[key] = sanitizeAttributeValue(key, rawValue);
	}
	return output;
}

function getExceptionText(error: unknown): {
	message?: string;
	stack?: string;
} {
	if (!(error instanceof Error)) return {};
	return {
		...(error.message ? { message: error.message } : {}),
		...(error.stack ? { stack: error.stack } : {}),
	};
}

function getTraceContext(span: Span | undefined): {
	traceId?: string;
	spanId?: string;
} {
	try {
		const spanContext = span?.spanContext();
		if (!spanContext || !spanContext.traceId || !spanContext.spanId) {
			return {};
		}
		return { traceId: spanContext.traceId, spanId: spanContext.spanId };
	} catch {
		return {};
	}
}

function getFingerprint(
	kind: FailureKind,
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): string[] {
	const toolName =
		attributes["mcp.tool.name"] ?? attributes["mcp.prompt.name"] ?? "none";
	const exceptionType = String(attributes["error.type"] ?? "UNKNOWN_ERROR");
	const errorCategory = attributes["error.category"]
		? String(attributes["error.category"])
		: String(diagnostic.category);
	return [
		"mcp",
		kind,
		String(toolName),
		exceptionType,
		errorCategory,
		String(
			attributes["error.code"] ??
				attributes["http.response.status_code"] ??
				"none",
		),
	];
}

function addErrorAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
	expected: boolean | undefined,
): void {
	if (expected) attributes["error.expected"] = true;
	attributes["error.category"] ??= diagnostic.category;
	if (diagnostic.code) attributes["error.code"] ??= diagnostic.code;
}

function addHttpAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): void {
	if (diagnostic.status !== undefined) {
		attributes["http.response.status_code"] ??= diagnostic.status;
	}
	if (diagnostic.method)
		attributes["http.request.method"] ??= diagnostic.method;
	if (diagnostic.endpoint)
		attributes["hevy.api.endpoint"] ??= diagnostic.endpoint;
}

function addExecutionAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): void {
	if (diagnostic.outcome) attributes["hevy.api.outcome"] ??= diagnostic.outcome;
	if (diagnostic.phase) attributes["hevy.api.phase"] ??= diagnostic.phase;
	if (diagnostic.operation_safety) {
		attributes["hevy.api.operation_safety"] ??= diagnostic.operation_safety;
	}
	if (diagnostic.commit_state) {
		attributes["hevy.api.commit_state"] ??= diagnostic.commit_state;
	}
	if (diagnostic.safe_to_retry !== undefined) {
		attributes["hevy.api.safe_to_retry"] ??= diagnostic.safe_to_retry;
	}
}

export function normalizeFailure(
	error: unknown,
	context: FailureContext,
): NormalizedFailure {
	const diagnostic = createSafeErrorDiagnostic(error);
	const attributes = copyAttributes(context.attributes);
	const exceptionType = diagnostic.category;
	const text = getExceptionText(error);
	const message =
		DIAGNOSTIC_DETAILS_ENABLED && text.message
			? sanitizeDiagnosticText(text.message)
			: undefined;
	const stack =
		DIAGNOSTIC_DETAILS_ENABLED && text.stack
			? sanitizeDiagnosticText(text.stack, MAX_STACK_LENGTH)
			: undefined;
	const responseError =
		DIAGNOSTIC_DETAILS_ENABLED && isHevyHttpError(error) && error.responseError
			? sanitizeDiagnosticText(error.responseError, MAX_ATTRIBUTE_LENGTH)
			: undefined;

	attributes["exception.type"] = exceptionType;
	addErrorAttributes(attributes, diagnostic, context.expected);
	addHttpAttributes(attributes, diagnostic);
	addExecutionAttributes(attributes, diagnostic);

	return {
		diagnostic,
		exceptionType,
		...(message ? { message } : {}),
		...(stack ? { stack } : {}),
		...(responseError ? { responseError } : {}),
		exception: {
			name: exceptionType,
			...(message ? { message } : {}),
			...(stack ? { stack } : {}),
		},
		attributes,
		fingerprint: getFingerprint(context.kind, attributes, diagnostic),
	};
}

function sanitizeContext(
	value: unknown,
): Record<string, TelemetryAttributeValue> {
	if (!isObject(value)) return {};
	const output: Record<string, TelemetryAttributeValue> = {};
	for (const [key, rawValue] of Object.entries(value).slice(0, 32)) {
		if (
			key !== "kind" &&
			!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))
		) {
			continue;
		}
		if (
			typeof rawValue !== "string" &&
			typeof rawValue !== "number" &&
			typeof rawValue !== "boolean"
		) {
			continue;
		}
		if (typeof rawValue === "number" && !Number.isFinite(rawValue)) {
			continue;
		}
		output[truncate(key, 128)] = sanitizeAttributeValue(key, rawValue);
	}
	return output;
}

function sanitizeSentryTags(tags: ErrorEvent["tags"]): ErrorEvent["tags"] {
	if (!tags) return undefined;
	const output: NonNullable<ErrorEvent["tags"]> = {};
	for (const [key, value] of Object.entries(tags)) {
		if (!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))) continue;
		if (
			typeof value !== "string" &&
			typeof value !== "number" &&
			typeof value !== "boolean"
		) {
			continue;
		}
		output[truncate(key, 128)] =
			typeof value === "string"
				? sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH)
				: value;
	}
	return output;
}

function normalizeStackFilename(value: string): string {
	const sanitized = sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH);
	const distMarker = sanitized.lastIndexOf("/dist/");
	return distMarker >= 0
		? `~${sanitized.slice(distMarker)}`
		: removeHomePath(sanitized);
}

function sanitizeSentryExceptionValues(
	event: ErrorEvent,
): ErrorEvent["exception"] {
	const values = event.exception?.values;
	if (!values) return undefined;
	return {
		values: values.map((value) => ({
			...(value.type
				? { type: sanitizeDiagnosticText(value.type, MAX_ATTRIBUTE_LENGTH) }
				: {}),
			...(value.value
				? { value: sanitizeDiagnosticText(value.value, MAX_MESSAGE_LENGTH) }
				: {}),
			stacktrace: value.stacktrace
				? {
						frames: value.stacktrace.frames?.map((frame) => ({
							...(frame.filename
								? {
										filename: normalizeStackFilename(frame.filename),
									}
								: {}),
							...(frame.function
								? {
										function: sanitizeDiagnosticText(
											frame.function,
											MAX_ATTRIBUTE_LENGTH,
										),
									}
								: {}),
							...(typeof frame.lineno === "number"
								? { lineno: frame.lineno }
								: {}),
							...(typeof frame.colno === "number"
								? { colno: frame.colno }
								: {}),
							...(typeof frame.in_app === "boolean"
								? { in_app: frame.in_app }
								: {}),
						})),
					}
				: undefined,
		})),
	};
}

/** Final Sentry-side safety net for SDK-generated event fields and integrations. */
export function sanitizeSentryEvent(
	event: ErrorEvent,
	_hint?: EventHint,
): ErrorEvent {
	return {
		...event,
		...(event.message
			? { message: sanitizeDiagnosticText(event.message, MAX_MESSAGE_LENGTH) }
			: {}),
		request: undefined,
		user: undefined,
		server_name: undefined,
		breadcrumbs: undefined,
		extra: undefined,
		logentry: undefined,
		threads: undefined,
		sdkProcessingMetadata: undefined,
		contexts: event.contexts?.mcp
			? { mcp: sanitizeContext(event.contexts.mcp) }
			: undefined,
		tags: sanitizeSentryTags(event.tags),
		exception: sanitizeSentryExceptionValues(event),
		spans: undefined,
	};
}

function createSentryError(record: NormalizedFailure): Error {
	const error = new Error(record.message ?? record.exceptionType);
	error.name = record.exceptionType;
	if (record.stack) error.stack = record.stack;
	return error;
}

function setSpanAttributes(span: Span, attributes: TelemetryAttributes): void {
	try {
		span.setAttributes(attributes);
	} catch {
		// Telemetry must never alter application behavior.
	}
}

const reportedErrors = new WeakSet<object>();
const diagnosticIds = new WeakMap<object, string>();

function getDiagnosticId(error: unknown): string | undefined {
	if (isObject(error)) {
		const existing = diagnosticIds.get(error);
		if (existing) return existing;
	}
	try {
		const generated = randomUUID();
		if (isObject(error)) diagnosticIds.set(error, generated);
		return generated;
	} catch {
		return undefined;
	}
}

function hasReportedError(error: unknown): boolean {
	if (!isObject(error)) return false;
	if (reportedErrors.has(error)) return true;
	reportedErrors.add(error);
	return false;
}

export function captureFailure(
	error: unknown,
	context: FailureContext,
): FailureReceipt | undefined {
	if (!TELEMETRY_ENABLED) return undefined;
	const span = context.span ?? trace.getActiveSpan() ?? undefined;
	const record = normalizeFailure(error, context);
	const traceContext = getTraceContext(span);
	if (traceContext.traceId) {
		record.attributes["otel.trace_id"] = traceContext.traceId;
	}
	if (traceContext.spanId) {
		record.attributes["otel.span_id"] = traceContext.spanId;
	}

	const diagnosticId = getDiagnosticId(error);
	if (diagnosticId) record.attributes["mcp.failure.id"] = diagnosticId;

	const duplicate = context.expected ? false : hasReportedError(error);
	let eventId: string | undefined;
	if (!duplicate && !context.expected) {
		try {
			eventId = Sentry.withScope((scope) => {
				for (const [key, value] of Object.entries(record.attributes)) {
					scope.setTag(key, String(value));
				}
				scope.setFingerprint([...record.fingerprint]);
				scope.setContext("mcp", {
					kind: context.kind,
					...record.attributes,
					...(record.responseError
						? { "hevy.api.response_error": record.responseError }
						: {}),
				});
				return Sentry.captureException(createSentryError(record));
			});
		} catch {
			// Sentry failures must never affect MCP behavior.
		}
	}

	if (span) {
		try {
			if (!duplicate && !context.expected) {
				span.recordException(record.exception);
				if (record.responseError) {
					span.addEvent("mcp.failure.detail", {
						"hevy.api.response_error": record.responseError,
					});
				}
			}
			setSpanAttributes(span, record.attributes);
			if (!context.expected) {
				span.setStatus({ code: SpanStatusCode.ERROR });
			}
			if (eventId) span.setAttribute("sentry.event_id", eventId);
		} catch {
			// OTel failures must never affect MCP behavior.
		}
	}

	return {
		...(diagnosticId ? { diagnosticId } : {}),
		...(eventId ? { eventId } : {}),
		...(traceContext.traceId ? { traceId: traceContext.traceId } : {}),
		...(traceContext.spanId ? { spanId: traceContext.spanId } : {}),
	};
}

/**
 * Centralized telemetry initialization.
 *
 * This module MUST be imported before any other application code.
 * It sets up independent telemetry paths: Sentry error events and an OTel
 * Collector (traces + metrics to Honeycomb).
 *
 * Sentry SDK: error monitoring, release tracking
 * OTel Collector → Honeycomb: performance traces, metrics
 */

import { randomBytes, randomUUID as nodeRandomUUID } from "node:crypto";
import * as Sentry from "@sentry/node";
import { metrics, trace } from "@opentelemetry/api";

import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import {
	AggregationTemporalityPreference,
	OTLPMetricExporter,
} from "@opentelemetry/exporter-metrics-otlp-http";
import { resourceFromAttributes } from "@opentelemetry/resources";
import {
	AlwaysOnSampler,
	BatchSpanProcessor,
	type SpanProcessor,
} from "@opentelemetry/sdk-trace-base";
import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";
import {
	MeterProvider,
	PeriodicExportingMetricReader,
} from "@opentelemetry/sdk-metrics";
import { captureFailure, sanitizeSentryEvent } from "./failure-reporter.js";
export type ProcessExceptionSource = {
	on(
		event: "uncaughtExceptionMonitor" | "unhandledRejection",
		listener: (error: unknown) => void,
	): void;
	removeListener(
		event: "uncaughtExceptionMonitor" | "unhandledRejection",
		listener: (error: unknown) => void,
	): void;
};

const PROCESS_FAILURE_TAXONOMY = {
	uncaughtException: "uncaught_exception",
	unhandledRejection: "unhandled_rejection",
} as const;

export function installProcessExceptionTracking(
	processLike: ProcessExceptionSource = process,
): () => void {
	if (!telemetryEnabled) return () => {};
	const recordProcessException = (
		source: keyof typeof PROCESS_FAILURE_TAXONOMY,
		error: unknown,
	) => {
		try {
			tracer.startActiveSpan(
				`mcp.process.${source}`,
				{ attributes: { "mcp.span.category": "process" } },
				(span) => {
					try {
						captureFailure(error, {
							kind: "process",
							attributes: {
								"exception.source": source,
								"mcp.failure.phase": PROCESS_FAILURE_TAXONOMY[source],
								"error.type": "MCP_PROCESS_EXCEPTION",
								"error.category": "McpProcessFailure",
							},
							span,
						});
					} finally {
						span.end();
					}
				},
			);
		} catch {
			// Process telemetry must never affect Node's lifecycle.
		}
	};
	const uncaughtException = (error: unknown) =>
		recordProcessException("uncaughtException", error);
	const unhandledRejection = (error: unknown) =>
		recordProcessException("unhandledRejection", error);
	processLike.on("uncaughtExceptionMonitor", uncaughtException);
	processLike.on("unhandledRejection", unhandledRejection);
	let cleaned = false;
	return () => {
		if (cleaned) return;
		cleaned = true;
		processLike.removeListener("uncaughtExceptionMonitor", uncaughtException);
		processLike.removeListener("unhandledRejection", unhandledRejection);
	};
}

declare const __HEVY_MCP_NAME__: string | undefined;
declare const __HEVY_MCP_VERSION__: string | undefined;
declare const __HEVY_MCP_BUILD__: boolean | undefined;
declare const __OTEL_COLLECTOR_TOKEN__: string | undefined;

const name =
	typeof __HEVY_MCP_NAME__ === "string" ? __HEVY_MCP_NAME__ : "hevy-mcp";
const version =
	typeof __HEVY_MCP_VERSION__ === "string" ? __HEVY_MCP_VERSION__ : "dev";

const telemetryEnabled = process.env.HEVY_MCP_TELEMETRY !== "0";

// Collector token is injected at build time from the OTEL_COLLECTOR_TOKEN
// GitHub secret via tsdown.config.ts define. The collector forwards
// traces and metrics to Honeycomb, keeping the Honeycomb API key off the
// client. The collector endpoint is public (behind Cloudflare Tunnel).
const collectorToken =
	typeof __OTEL_COLLECTOR_TOKEN__ === "string" && __OTEL_COLLECTOR_TOKEN__
		? __OTEL_COLLECTOR_TOKEN__
		: (process.env.OTEL_COLLECTOR_TOKEN ?? "");

const COLLECTOR_ENDPOINT = "https://otel.chrisdoc.dev/v1";
const DEFAULT_SENTRY_DSN =
	"https://ce696d8333b507acbf5203eb877bce0f@o4508975499575296.ingest.de.sentry.io/4509049671647312";
const sentryRelease = process.env.SENTRY_RELEASE ?? `${name}@${version}`;

export function createServiceInstanceId(
	generate: () => string = nodeRandomUUID,
): string {
	try {
		const generated = generate();
		if (generated.length > 0 && generated.length <= 128) return generated;
	} catch {
		// Fall back to a process-local opaque identifier.
	}
	return randomBytes(16).toString("hex");
}

const serviceInstanceId = createServiceInstanceId();

const resource = resourceFromAttributes({
	"service.name": name,
	"service.version": version,
	"service.instance.id": serviceInstanceId,
	"process.runtime.name": process.release.name,
	"process.runtime.version": process.version,
});

let tracerProvider: NodeTracerProvider | undefined;
let meterProvider: MeterProvider | undefined;

if (telemetryEnabled) {
	const rawDsn = process.env.SENTRY_DSN ?? DEFAULT_SENTRY_DSN;
	const isValidDsn =
		typeof rawDsn === "string" && rawDsn.length > 0 && !rawDsn.startsWith("*");

	// --- Sentry error monitoring ---
	Sentry.init({
		dsn: isValidDsn ? rawDsn : undefined,
		release: sentryRelease,
		tracesSampleRate: 0.0,
		sendClientReports: false,
		sendDefaultPii: false,
		beforeSend: sanitizeSentryEvent,
		integrations: (integrations) =>
			integrations.filter(
				(integration) =>
					integration.name !== "OnUncaughtException" &&
					integration.name !== "OnUnhandledRejection",
			),
		skipOpenTelemetrySetup: true,
		registerEsmLoaderHooks: false,
		ignoreErrors: ["EPIPE", "broken pipe"],
	});

	const spanProcessors: SpanProcessor[] = [];

	// OTel Collector → Honeycomb traces — only if token is available
	if (collectorToken) {
		spanProcessors.push(
			new BatchSpanProcessor(
				new OTLPTraceExporter({
					url: `${COLLECTOR_ENDPOINT}/traces`,
					headers: {
						Authorization: `Bearer ${collectorToken}`,
					},
				}),
			),
		);
	}

	tracerProvider = new NodeTracerProvider({
		resource,
		sampler: new AlwaysOnSampler(),
		spanProcessors,
	});

	tracerProvider.register();

	// --- OpenTelemetry meter provider (→ Collector → Honeycomb metrics) ---
	if (collectorToken) {
		meterProvider = new MeterProvider({
			resource,
			readers: [
				new PeriodicExportingMetricReader({
					exporter: new OTLPMetricExporter({
						url: `${COLLECTOR_ENDPOINT}/metrics`,
						headers: {
							Authorization: `Bearer ${collectorToken}`,
						},
						temporalityPreference: AggregationTemporalityPreference.DELTA,
					}),
					exportIntervalMillis: 30_000,
				}),
			],
		});
		metrics.setGlobalMeterProvider(meterProvider);
	}

	trace.setGlobalTracerProvider(tracerProvider);
}

export async function flushTelemetry(timeoutMs = 1_000): Promise<void> {
	if (!telemetryEnabled) {
		return;
	}

	const flushPromise = Promise.allSettled([
		...(tracerProvider ? [tracerProvider.forceFlush()] : []),
		...(meterProvider ? [meterProvider.forceFlush()] : []),
		Sentry.flush(timeoutMs),
	]);
	let timeout: ReturnType<typeof setTimeout> | undefined;
	const timeoutPromise = new Promise<void>((resolve) => {
		timeout = setTimeout(resolve, timeoutMs);
	});
	try {
		await Promise.race([flushPromise, timeoutPromise]);
	} finally {
		clearTimeout(timeout);
	}
}

// --- Shared instances for the rest of the codebase ---
export const tracer = trace.getTracer(name);
export const meter = metrics.getMeter(name);

/**
 * Bundled service identity — avoids passing name and version as
 * separate primitives throughout the codebase (Data Clumps smell).
 */
export interface ServiceInfo {
	readonly name: string;
	readonly version: string;
}

export const serviceInfo: ServiceInfo = { name, version } as const;
export const serviceName = name;
export const serviceVersion = version;
export { serviceInstanceId };
export {
	captureFailure,
	normalizeFailure,
	sanitizeDiagnosticText,
	sanitizeSentryEvent,
} from "./failure-reporter.js";
export type {
	FailureContext,
	FailureKind,
	FailureReceipt,
	NormalizedFailure,
	TelemetryAttributeValue,
	TelemetryAttributes,
} from "./failure-reporter.js";

/// <reference types="node" />
import { readFileSync } from "node:fs";
import { codecovRollupPlugin } from "@codecov/rollup-plugin";
import { sentryRollupPlugin } from "@sentry/rollup-plugin";
import { defineConfig } from "tsdown";

interface PackageJsonMeta {
	name?: unknown;
	version?: unknown;
}

const pkgJsonRaw = readFileSync(
	new URL("./package.json", import.meta.url),
	"utf-8",
);
let parsed: PackageJsonMeta;
try {
	parsed = JSON.parse(pkgJsonRaw) as PackageJsonMeta;
} catch (error) {
	throw new Error(`Failed to parse package.json: ${(error as Error).message}`);
}

const { name, version } = parsed;
const isStandaloneBuild = process.env.HEVY_MCP_BUILD_MODE === "standalone";
const isReleaseBuild = process.env.HEVY_MCP_RELEASE === "true";
const codecovToken = process.env.CODECOV_TOKEN?.trim() || undefined;
const enableCodecovBundleAnalysis =
	!isStandaloneBuild && codecovToken !== undefined;

if (process.env.HEVY_MCP_RELEASE === "true") {
	const missing: string[] = [];
	if (!process.env.OTEL_COLLECTOR_TOKEN) missing.push("OTEL_COLLECTOR_TOKEN");
	if (!process.env.SENTRY_ORG) missing.push("SENTRY_ORG");
	if (!process.env.SENTRY_PROJECT) missing.push("SENTRY_PROJECT");
	if (!process.env.SENTRY_AUTH_TOKEN) missing.push("SENTRY_AUTH_TOKEN");

	if (missing.length > 0) {
		throw new Error(
			`Release build failed: Missing required environment variables: ${missing.join(
				", ",
			)}`,
		);
	}
}

if (
	typeof name !== "string" ||
	typeof version !== "string" ||
	!name ||
	!version
) {
	throw new Error(
		`package.json must provide non-empty string 'name' and 'version'. Got name=${String(
			name,
		)}, version=${String(version)}`,
	);
}

const packageName = name as string;
const packageVersion = version as string;

function createReleaseSentryPlugin() {
	const [plugin] = sentryRollupPlugin({
		org: process.env.SENTRY_ORG,
		project: process.env.SENTRY_PROJECT,
		authToken: process.env.SENTRY_AUTH_TOKEN,
		telemetry: false,
		sourcemaps: {
			assets: ["./dist/**/*.mjs", "./dist/**/*.map"],
			filesToDeleteAfterUpload: ["./dist/**/*.map"],
		},
		release: {
			name: `${packageName}@${packageVersion}`,
			inject: false,
		},
	});
	if (!plugin) throw new Error("Sentry release plugin was not created");

	const originalRenderChunk = plugin.renderChunk;
	return {
		...plugin,
		renderChunk(
			code: string,
			chunk: { facadeModuleId?: string | null; moduleIds?: string[] },
			options: unknown,
			meta: unknown,
		) {
			const normalizeModuleId = (moduleId: string) =>
				moduleId.replaceAll("\\", "/");
			const isExecutableModule = (moduleId: string | null | undefined) => {
				const normalized = moduleId && normalizeModuleId(moduleId);
				return (
					normalized === "src/cli.ts" ||
					normalized?.endsWith("/src/cli.ts") ||
					normalized === "src/runtime.ts" ||
					normalized?.endsWith("/src/runtime.ts")
				);
			};
			// The published package root is an embedding surface. Inject Sentry
			// debug IDs into the executable entry and its lazy runtime chunk;
			// shared chunks imported by the embedding entry must remain inert.
			const isExecutableChunk = [
				chunk.facadeModuleId,
				...(chunk.moduleIds ?? []),
			].some(isExecutableModule);
			if (!isExecutableChunk) return null;
			return originalRenderChunk?.call(this, code, chunk, options, meta);
		},
	};
}

