		recordMcpToolFailure();

		expect(resolveSessionTerminationCategory(true)).toBe("tool_failure");
		recordMcpSessionTermination("tool_failure");
		expect(testDoubles.sessionEndedAdd).toHaveBeenCalledWith(
			1,
			expect.objectContaining({
				termination_category: "tool_failure",
				tool_calls_bucket: "1",
			}),
		);
	});
	it("isolates opaque IDs across sessions and propagates the active ID", () => {
		const first = createMcpSessionContext({ method: "initialize" }, "http", {
			telemetrySessionId: "session-one",
		});
		const second = createMcpSessionContext({ method: "initialize" }, "http", {
			telemetrySessionId: "session-two",
		});

		expect(first.telemetrySessionId).not.toBe(second.telemetrySessionId);
		expect(
			runWithMcpSessionContext(first, () => getCurrentMcpSessionId()),
		).toBe("session-one");
		expect(
			runWithMcpSessionContext(second, () => getCurrentMcpSessionId()),
		).toBe("session-two");
		runWithMcpSessionContext(first, () =>
			recordMcpSessionStart({}, "http", first),
		);
		expect(testDoubles.sessionStartedAdd.mock.calls.flat()).not.toContain(
			"session-one",
		);
	});
	it("keeps telemetry session IDs out of metric attributes", () => {
		const context = createMcpSessionContext(
			{
				method: "initialize",
				params: {
					protocolVersion: "2025-11-25",
					clientInfo: { name: "Private Client", version: "1.2.3" },
				},
			},
			"http",
			{ telemetrySessionId: "session-secret" },
		);

		runWithMcpSessionContext(context, () => {
			recordMcpSessionStart({}, "http", context);
			recordMcpSessionTermination("clean", context);
		});

		expect(
			JSON.stringify([
				testDoubles.sessionStartedAdd.mock.calls,
				testDoubles.sessionEndedAdd.mock.calls,
			]),
		).not.toContain("session-secret");
	});
	it("generates one injectable opaque ID per session", () => {
		const generate = vi.fn(() => "generated-session");
		const context = createMcpSessionContext({ method: "initialize" }, "stdio", {
			generateTelemetrySessionId: generate,
		});

		expect(context.telemetrySessionId).toBe("generated-session");
		expect(generate).toHaveBeenCalledOnce();
	});
});

import { AsyncLocalStorage } from "node:async_hooks";
import { SpanStatusCode, trace, type Span } from "@opentelemetry/api";
import { createSafeErrorDiagnostic, ErrorType } from "@hevy-mcp/core";
import type { NodeTransport } from "./arguments.js";
import {
	getCurrentMcpSessionId,
	getCurrentMcpTransport,
} from "./mcp-session-observability.js";
import { projectExecutionAttributes } from "./execution-telemetry.js";
import { captureFailure, tracer } from "./telemetry.js";

type SdkRequestHandler = (request: unknown, extra: unknown) => Promise<unknown>;

interface SdkProtocolInternals {
	_requestHandlers?: Map<string, SdkRequestHandler>;
}

interface ToolRequestLike {
	params?: { name?: unknown };
}

interface SdkToolErrorHost {
	createToolError?: (message: string) => unknown;
}

interface ToolResultLike {
	isError?: unknown;
}

type FailureAttributes = Record<string, string | number | boolean>;
type SdkFailureKind = "protocol" | "tool_call" | "validation";
type SdkValidationKind = "input" | "output" | "tool_not_found" | "unknown";

type SdkFailureOptions = {
	expected?: boolean;
	validationKind?: SdkValidationKind;
};

const sdkToolNameStorage = new AsyncLocalStorage<string>();
const sdkRequestStateStorage = new AsyncLocalStorage<{
	expectedValidation?: boolean;
}>();
const SAFE_TOOL_NAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/u;
const SDK_FAILURE_TAXONOMY: Record<
	SdkFailureKind,
	{ errorType: ErrorType; errorCategory: string }
> = {
	protocol: {
		errorType: ErrorType.UNKNOWN_ERROR,
		errorCategory: "McpSdkProtocolFailure",
	},
	tool_call: {
		errorType: ErrorType.UNKNOWN_ERROR,
		errorCategory: "McpSdkToolCallFailure",
	},
	validation: {
		errorType: ErrorType.VALIDATION_ERROR,
		errorCategory: "McpSdkValidationFailure",
	},
};

function createFailureAttributes(
	error: unknown,
	phase: "discovery" | "sdk",
	errorType: string,
	errorCategory: string,
): FailureAttributes {
	const diagnostic = createSafeErrorDiagnostic(error);
	return {
		"mcp.failure.phase": phase,
		"error.type": errorType,
		"error.category": errorCategory,
		...(diagnostic.code ? { "error.code": diagnostic.code } : {}),
		...(diagnostic.status !== undefined
			? { "http.response.status_code": diagnostic.status }
			: {}),
		...(diagnostic.method ? { "http.request.method": diagnostic.method } : {}),
		...(diagnostic.endpoint
			? { "hevy.api.endpoint": diagnostic.endpoint }
			: {}),
		...projectExecutionAttributes(diagnostic),
	};
}

function enrichActiveSdkSpan(attributes: FailureAttributes): void {
	try {
		trace.getActiveSpan()?.setAttributes(attributes);
	} catch {
		// SDK span enrichment is best-effort and cannot affect protocol handling.
	}
}

function getSdkToolName(request: unknown): string {
	if (!request || typeof request !== "object") return "unknown";
	const candidate = (request as ToolRequestLike).params?.name;
	return typeof candidate === "string" && SAFE_TOOL_NAME_PATTERN.test(candidate)
		? candidate
		: "unknown";
}

function markSdkToolFailure(
	span: Span,
	error: unknown,
	toolName = sdkToolNameStorage.getStore() ?? "unknown",
	kind: SdkFailureKind = "tool_call",
	options: SdkFailureOptions = {},
): void {
	const taxonomy = SDK_FAILURE_TAXONOMY[kind];
	const attributes: FailureAttributes = {
		"mcp.tool.name": toolName,
		...createFailureAttributes(
			error,
			"sdk",
			taxonomy.errorType,
			taxonomy.errorCategory,
		),
		...(options.validationKind
			? { "mcp.validation.kind": options.validationKind }
			: {}),
	};
	span.addEvent("mcp.tool.failure", attributes);
	span.setAttribute("error.type", taxonomy.errorType);
	captureFailure(error, {
		kind: "sdk",
		attributes,
		span,
		expected: options.expected,
	});
	if (options.expected !== true) {
		span.setStatus({ code: SpanStatusCode.ERROR });
	}
}

function installProtocolErrorTracking(
	server: { server?: { onerror?: (error: Error) => void } },
	transport: NodeTransport,
): void {
	const protocol = server.server;
	if (!protocol) return;
	const previous = protocol.onerror;
	protocol.onerror = (error) => {
		const taxonomy = SDK_FAILURE_TAXONOMY.protocol;
		const attributes = createFailureAttributes(
			error,
			"sdk",
			taxonomy.errorType,
			taxonomy.errorCategory,
		);
		const activeSpan = trace.getActiveSpan();
		const sessionId = getCurrentMcpSessionId();
		if (activeSpan) {
			activeSpan.addEvent("mcp.tool.failure", {
				"mcp.tool.name": sdkToolNameStorage.getStore() ?? "unknown",
				...attributes,
			});
			captureFailure(error, {
				kind: "protocol",
				attributes,
				span: activeSpan,
			});
		} else {
			tracer.startActiveSpan(
				"mcp.sdk.failure",
				{
					attributes: {
						"mcp.span.category": "protocol",
						"mcp.transport": transport,
						...(sessionId ? { "mcp.session.id": sessionId } : {}),
					},
				},
				(span) => {
					span.addEvent("mcp.tool.failure", {
						"mcp.tool.name": "unknown",
						...attributes,
					});
					captureFailure(error, { kind: "protocol", attributes, span });
					span.end();
				},
			);
		}
		try {
			previous?.(error);
		} catch {
			// Existing SDK/Sentry handlers must not affect protocol behavior.
		}
	};
}

function classifySdkValidation(message: string): {
	kind: SdkValidationKind;
	expected: boolean;
	toolName?: string;
} {
	const inputValidation =
		/^Input validation error: Invalid arguments for tool ([A-Za-z0-9][A-Za-z0-9._-]{0,63})(?::|$)/u.exec(
			message,
		);
	if (inputValidation) {
		return {
			kind: "input",
			expected: true,
			toolName: inputValidation[1],
		};
	}
	if (message.startsWith("Input validation error:")) {
		return { kind: "input", expected: true };
	}
	if (message.startsWith("Output validation error:")) {
		return { kind: "output", expected: false };
	}
	const missingTool =
		/^Tool ([A-Za-z0-9][A-Za-z0-9._-]{0,63}) not found$/u.exec(message);
	if (missingTool) {
		return {
			kind: "tool_not_found",
			expected: true,
			toolName: missingTool[1],
		};
	}
	return { kind: "unknown", expected: false };
}

function installValidationErrorTracking(server: object): void {
	const toolErrorHost = server as SdkToolErrorHost;
	const previousCreateToolError = toolErrorHost.createToolError;
	if (!previousCreateToolError) return;
	const createToolError = previousCreateToolError.bind(server);
	toolErrorHost.createToolError = (message) => {
		const validation = classifySdkValidation(message);
		const requestState = sdkRequestStateStorage.getStore();
		if (requestState) requestState.expectedValidation = validation.expected;
		const result = createToolError(message);
		const activeSpan = trace.getActiveSpan();
		if (activeSpan) {
			markSdkToolFailure(
				activeSpan,
				new Error(
					validation.kind === "output"
						? "MCP tool output validation failed"
						: "MCP tool validation failed",
				),
				sdkToolNameStorage.getStore() ?? validation.toolName ?? "unknown",
				"validation",
				{
					expected: validation.expected,
					validationKind: validation.kind,
				},
			);
		}
		return result;
	};
}

function installInitializeEnrichment(
	handlers: Map<string, SdkRequestHandler>,
	transport: NodeTransport,
): void {
	const initializeHandler = handlers.get("initialize");
	if (!initializeHandler) return;
	handlers.set("initialize", (request, extra) => {
		enrichActiveSdkSpan({
			"mcp.span.category": "protocol",
			"mcp.transport": transport,
		});
		return initializeHandler(request, extra);
	});
}

function installToolCallTracking(
	handlers: Map<string, SdkRequestHandler>,
	transport: NodeTransport,
): void {
	const toolHandler = handlers.get("tools/call");
	if (!toolHandler) return;
	handlers.set("tools/call", (request, extra) => {
		const sessionId = getCurrentMcpSessionId();
		const toolName = getSdkToolName(request);
		const attributes = {
			"mcp.span.category": "protocol",
			"mcp.transport": transport,
			"mcp.operation.kind": "tool",
			"mcp.tool.name": toolName,
			...(sessionId ? { "mcp.session.id": sessionId } : {}),
		};
		enrichActiveSdkSpan(attributes);
		return sdkToolNameStorage.run(toolName, () =>
			sdkRequestStateStorage.run({}, () =>
				tracer.startActiveSpan(
					"mcp.sdk.tools.call",
					{ attributes },
					async (span) => {
						try {
							const result = (await toolHandler(
								request,
								extra,
							)) as ToolResultLike;
							if (result?.isError === true) {
								span.setAttribute("mcp.tool.outcome", "returned_error");
								if (
									sdkRequestStateStorage.getStore()?.expectedValidation !== true
								) {
									span.setStatus({ code: SpanStatusCode.ERROR });
								}
							} else {
								span.setStatus({ code: SpanStatusCode.OK });
							}
							return result;
						} catch (error) {
							const validation =
								error instanceof Error
									? classifySdkValidation(error.message)
									: { kind: "unknown" as const, expected: false };
							if (validation.kind === "tool_not_found") {
								markSdkToolFailure(span, error, toolName, "validation", {
									expected: true,
									validationKind: validation.kind,
								});
							} else {
								markSdkToolFailure(span, error, toolName);
							}
							throw error;
						} finally {
							span.end();
						}
					},
				),
			),
		);
	});
}

function installDiscoveryTracking(
	handlers: Map<string, SdkRequestHandler>,
): void {
	const discoveryHandler = handlers.get("server/discover");
	if (!discoveryHandler) return;
	handlers.set("server/discover", (request, extra) => {
		const sessionId = getCurrentMcpSessionId();
		return tracer.startActiveSpan(
			"mcp.server.discover",
			{
				attributes: {
					"mcp.span.category": "discovery",
					"mcp.transport": getCurrentMcpTransport(),
					...(sessionId ? { "mcp.session.id": sessionId } : {}),
				},
			},
			async (span) => {
				try {
					const result = await discoveryHandler(request, extra);
					span.setStatus({ code: SpanStatusCode.OK });
					return result;
				} catch (error) {
					const attributes = createFailureAttributes(
						error,
						"discovery",
						ErrorType.UNKNOWN_ERROR,
						"McpServerDiscoveryFailure",
					);
					span.addEvent("mcp.discovery.failure", attributes);
					captureFailure(error, { kind: "discovery", attributes, span });
					throw error;
				} finally {
					span.end();
				}
			},
		);
	});
}

export function installSdkErrorTracking(
	server: { server?: { onerror?: (error: Error) => void } },
	transport: NodeTransport,
): void {
	installProtocolErrorTracking(server, transport);
	installValidationErrorTracking(server);
	const handlers = (server.server as SdkProtocolInternals | undefined)
		?._requestHandlers;
	if (!(handlers instanceof Map)) return;
	installInitializeEnrichment(handlers, transport);
	installToolCallTracking(handlers, transport);
	installDiscoveryTracking(handlers);
}

import { randomUUID } from "node:crypto";
import { createSafeErrorDiagnostic } from "@hevy-mcp/core";
import { isHevyHttpError } from "@hevy-mcp/hevy-client";
import * as Sentry from "@sentry/node";
import { SpanStatusCode, trace, type Span } from "@opentelemetry/api";
import type { ErrorEvent, EventHint } from "@sentry/node";

type SafeErrorDiagnostic = ReturnType<typeof createSafeErrorDiagnostic>;

export type TelemetryAttributeValue = string | number | boolean;
export type TelemetryAttributes = Record<string, TelemetryAttributeValue>;

export type FailureKind =
	| "api"
	| "discovery"
	| "lifecycle"
	| "process"
	| "protocol"
	| "prompt"
	| "sdk"
	| "tool";

export interface FailureContext {
	readonly kind: FailureKind;
	readonly attributes?: TelemetryAttributes;
	readonly expected?: boolean;
	readonly span?: Span;
}

export interface NormalizedFailure {
	readonly diagnostic: SafeErrorDiagnostic;
	readonly exceptionType: string;
	readonly message?: string;
	readonly stack?: string;
	readonly responseError?: string;
	readonly exception: {
		readonly name: string;
		readonly message?: string;
		readonly stack?: string;
	};
	readonly attributes: TelemetryAttributes;
	readonly fingerprint: readonly string[];
}

export interface FailureReceipt {
	readonly diagnosticId?: string;
	readonly eventId?: string;
	readonly traceId?: string;
	readonly spanId?: string;
}

const MAX_ATTRIBUTE_LENGTH = 256;
const MAX_MESSAGE_LENGTH = 2_048;
const MAX_STACK_LENGTH = 16_384;
const SAFE_TAG_PREFIXES = [
	"error.",
	"exception.",
	"hevy.",
	"http.",
	"mcp.",
	"otel.",
	"service.",
] as const;
const TELEMETRY_ENABLED = process.env.HEVY_MCP_TELEMETRY !== "0";
const DIAGNOSTIC_DETAILS_ENABLED =
	process.env.HEVY_MCP_TELEMETRY_DIAGNOSTICS !== "0";

function isObject(value: unknown): value is object {
	return typeof value === "object" && value !== null;
}

function truncate(value: string, length: number): string {
	return value.length > length ? `${value.slice(0, length - 1)}…` : value;
}

function escapeRegExp(value: string): string {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function removeHomePath(value: string): string {
	const home = process.env.HOME?.trim();
	const withConfiguredHome = home
		? value.replace(new RegExp(escapeRegExp(home), "g"), "~")
		: value;
	return withConfiguredHome.replace(/\/(?:Users|home)\/[^/\s]+/g, "~");
}

const EMAIL = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi;

function removeControlCharacters(value: string): string {
	let output = "";
	let inEscapeSequence = false;
	for (const character of value) {
		const codePoint = character.codePointAt(0) ?? 0;
		if (inEscapeSequence) {
			if (codePoint >= 0x40 && codePoint <= 0x7e) {
				inEscapeSequence = false;
			}
			continue;
		}
		if (codePoint === 0x1b) {
			inEscapeSequence = true;
			continue;
		}
		if (
			codePoint <= 0x1f &&
			codePoint !== 0x09 &&
			codePoint !== 0x0a &&
			codePoint !== 0x0d
		) {
			continue;
		}
		if (codePoint === 0x7f) continue;
		output += character;
	}
	return output;
}

/** Remove common credentials and URL payloads without inspecting object fields. */
export function sanitizeDiagnosticText(
	value: string,
	maxLength = MAX_MESSAGE_LENGTH,
): string {
	const withoutControlCharacters = removeControlCharacters(value);
	const withoutSecrets = withoutControlCharacters
		.replace(/\bBearer\s+[^\s,;]+/gi, "Bearer [REDACTED]")
		.replace(
			/\b(api[-_ ]?key|authorization|password|secret|token)\s*[:=]\s*(?:"[^"]*"|'[^']*'|[^\s,;]+)/gi,
			"$1=[REDACTED]",
		)
		.replace(EMAIL, "[EMAIL_REDACTED]")
		.replace(/\bhttps?:\/\/[^\s)<>]+/gi, "[URL]");
	return truncate(removeHomePath(withoutSecrets).trim(), maxLength);
}

function sanitizeAttributeValue(
	_key: string,
	value: TelemetryAttributeValue,
): TelemetryAttributeValue {
	if (typeof value !== "string") return value;
	return sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH);
}

function copyAttributes(
	attributes: TelemetryAttributes | undefined,
): TelemetryAttributes {
	if (!attributes) return {};
	const output: TelemetryAttributes = {};
	for (const [rawKey, rawValue] of Object.entries(attributes)) {
		const key = truncate(rawKey, 128);
		if (
			!key ||
			!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix)) ||
			(typeof rawValue === "number" && !Number.isFinite(rawValue))
		) {
			continue;
		}
		output[key] = sanitizeAttributeValue(key, rawValue);
	}
	return output;
}

function getExceptionText(error: unknown): {
	message?: string;
	stack?: string;
} {
	if (!(error instanceof Error)) return {};
	return {
		...(error.message ? { message: error.message } : {}),
		...(error.stack ? { stack: error.stack } : {}),
	};
}

function getTraceContext(span: Span | undefined): {
	traceId?: string;
	spanId?: string;
} {
	try {
		const spanContext = span?.spanContext();
		if (!spanContext || !spanContext.traceId || !spanContext.spanId) {
			return {};
		}
		return { traceId: spanContext.traceId, spanId: spanContext.spanId };
	} catch {
		return {};
	}
}

function getFingerprint(
	kind: FailureKind,
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): string[] {
	const toolName =
		attributes["mcp.tool.name"] ?? attributes["mcp.prompt.name"] ?? "none";
	const exceptionType = String(attributes["error.type"] ?? "UNKNOWN_ERROR");
	const errorCategory = attributes["error.category"]
		? String(attributes["error.category"])
		: String(diagnostic.category);
	return [
		"mcp",
		kind,
		String(toolName),
		exceptionType,
		errorCategory,
		String(
			attributes["error.code"] ??
				attributes["http.response.status_code"] ??
				"none",
		),
	];
}

function addErrorAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
	expected: boolean | undefined,
): void {
	if (expected) attributes["error.expected"] = true;
	attributes["error.category"] ??= diagnostic.category;
	if (diagnostic.code) attributes["error.code"] ??= diagnostic.code;
}

function addHttpAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): void {
	if (diagnostic.status !== undefined) {
		attributes["http.response.status_code"] ??= diagnostic.status;
	}
	if (diagnostic.method)
		attributes["http.request.method"] ??= diagnostic.method;
	if (diagnostic.endpoint)
		attributes["hevy.api.endpoint"] ??= diagnostic.endpoint;
}

function addExecutionAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): void {
	if (diagnostic.outcome) attributes["hevy.api.outcome"] ??= diagnostic.outcome;
	if (diagnostic.phase) attributes["hevy.api.phase"] ??= diagnostic.phase;
	if (diagnostic.operation_safety) {
		attributes["hevy.api.operation_safety"] ??= diagnostic.operation_safety;
	}
	if (diagnostic.commit_state) {
		attributes["hevy.api.commit_state"] ??= diagnostic.commit_state;
	}
	if (diagnostic.safe_to_retry !== undefined) {
		attributes["hevy.api.safe_to_retry"] ??= diagnostic.safe_to_retry;
	}
}

export function normalizeFailure(
	error: unknown,
	context: FailureContext,
): NormalizedFailure {
	const diagnostic = createSafeErrorDiagnostic(error);
	const attributes = copyAttributes(context.attributes);
	const exceptionType = diagnostic.category;
	const text = getExceptionText(error);
	const message =
		DIAGNOSTIC_DETAILS_ENABLED && text.message
			? sanitizeDiagnosticText(text.message)
			: undefined;
	const stack =
		DIAGNOSTIC_DETAILS_ENABLED && text.stack
			? sanitizeDiagnosticText(text.stack, MAX_STACK_LENGTH)
			: undefined;
	const responseError =
		DIAGNOSTIC_DETAILS_ENABLED && isHevyHttpError(error) && error.responseError
			? sanitizeDiagnosticText(error.responseError, MAX_ATTRIBUTE_LENGTH)
			: undefined;

	attributes["exception.type"] = exceptionType;
	addErrorAttributes(attributes, diagnostic, context.expected);
	addHttpAttributes(attributes, diagnostic);
	addExecutionAttributes(attributes, diagnostic);

	return {
		diagnostic,
		exceptionType,
		...(message ? { message } : {}),
		...(stack ? { stack } : {}),
		...(responseError ? { responseError } : {}),
		exception: {
			name: exceptionType,
			...(message ? { message } : {}),
			...(stack ? { stack } : {}),
		},
		attributes,
		fingerprint: getFingerprint(context.kind, attributes, diagnostic),
	};
}

function sanitizeContext(
	value: unknown,
): Record<string, TelemetryAttributeValue> {
	if (!isObject(value)) return {};
	const output: Record<string, TelemetryAttributeValue> = {};
	for (const [key, rawValue] of Object.entries(value).slice(0, 32)) {
		if (
			key !== "kind" &&
			!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))
		) {
			continue;
		}
		if (
			typeof rawValue !== "string" &&
			typeof rawValue !== "number" &&
			typeof rawValue !== "boolean"
		) {
			continue;
		}
		if (typeof rawValue === "number" && !Number.isFinite(rawValue)) {
			continue;
		}
		output[truncate(key, 128)] = sanitizeAttributeValue(key, rawValue);
	}
	return output;
}

function sanitizeSentryTags(tags: ErrorEvent["tags"]): ErrorEvent["tags"] {
	if (!tags) return undefined;
	const output: NonNullable<ErrorEvent["tags"]> = {};
	for (const [key, value] of Object.entries(tags)) {
		if (!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))) continue;
		if (
			typeof value !== "string" &&
			typeof value !== "number" &&
			typeof value !== "boolean"
		) {
			continue;
		}
		output[truncate(key, 128)] =
			typeof value === "string"
				? sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH)
				: value;
	}
	return output;
}

function normalizeStackFilename(value: string): string {
	const sanitized = sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH);
	const distMarker = sanitized.lastIndexOf("/dist/");
	return distMarker >= 0
		? `~${sanitized.slice(distMarker)}`
		: removeHomePath(sanitized);
}

function sanitizeSentryExceptionValues(
	event: ErrorEvent,
): ErrorEvent["exception"] {
	const values = event.exception?.values;
	if (!values) return undefined;
	return {
		values: values.map((value) => ({
			...(value.type
				? { type: sanitizeDiagnosticText(value.type, MAX_ATTRIBUTE_LENGTH) }
				: {}),
			...(value.value
				? { value: sanitizeDiagnosticText(value.value, MAX_MESSAGE_LENGTH) }
				: {}),
			stacktrace: value.stacktrace
				? {
						frames: value.stacktrace.frames?.map((frame) => ({
							...(frame.filename
								? {
										filename: normalizeStackFilename(frame.filename),
									}
								: {}),
							...(frame.function
								? {
										function: sanitizeDiagnosticText(
											frame.function,
											MAX_ATTRIBUTE_LENGTH,
										),
									}
								: {}),
							...(typeof frame.lineno === "number"
								? { lineno: frame.lineno }
								: {}),
							...(typeof frame.colno === "number"
								? { colno: frame.colno }
								: {}),
							...(typeof frame.in_app === "boolean"
								? { in_app: frame.in_app }
								: {}),
						})),
					}
				: undefined,
		})),
	};
}

/** Final Sentry-side safety net for SDK-generated event fields and integrations. */
export function sanitizeSentryEvent(
	event: ErrorEvent,
	_hint?: EventHint,
): ErrorEvent {
	return {
		...event,
		...(event.message
			? { message: sanitizeDiagnosticText(event.message, MAX_MESSAGE_LENGTH) }
			: {}),
		request: undefined,
		user: undefined,
		server_name: undefined,
		breadcrumbs: undefined,
		extra: undefined,
		logentry: undefined,
		threads: undefined,
		sdkProcessingMetadata: undefined,
		contexts: event.contexts?.mcp
			? { mcp: sanitizeContext(event.contexts.mcp) }
			: undefined,
		tags: sanitizeSentryTags(event.tags),
		exception: sanitizeSentryExceptionValues(event),
		spans: undefined,
	};
}

function createSentryError(record: NormalizedFailure): Error {
	const error = new Error(record.message ?? record.exceptionType);
	error.name = record.exceptionType;
	if (record.stack) error.stack = record.stack;
	return error;
}

function setSpanAttributes(span: Span, attributes: TelemetryAttributes): void {
	try {
		span.setAttributes(attributes);
	} catch {
		// Telemetry must never alter application behavior.
	}
}

const reportedErrors = new WeakSet<object>();
const diagnosticIds = new WeakMap<object, string>();

function getDiagnosticId(error: unknown): string | undefined {
	if (isObject(error)) {
		const existing = diagnosticIds.get(error);
		if (existing) return existing;
	}
	try {
		const generated = randomUUID();
		if (isObject(error)) diagnosticIds.set(error, generated);
		return generated;
	} catch {
		return undefined;
	}
}

function hasReportedError(error: unknown): boolean {
	if (!isObject(error)) return false;
	if (reportedErrors.has(error)) return true;
	reportedErrors.add(error);
	return false;
}

export function captureFailure(
	error: unknown,
	context: FailureContext,
): FailureReceipt | undefined {
	if (!TELEMETRY_ENABLED) return undefined;
	const span = context.span ?? trace.getActiveSpan() ?? undefined;
	const record = normalizeFailure(error, context);
	const traceContext = getTraceContext(span);
	if (traceContext.traceId) {
		record.attributes["otel.trace_id"] = traceContext.traceId;
	}
	if (traceContext.spanId) {
		record.attributes["otel.span_id"] = traceContext.spanId;
	}

	const diagnosticId = getDiagnosticId(error);
	if (diagnosticId) record.attributes["mcp.failure.id"] = diagnosticId;

	const duplicate = context.expected ? false : hasReportedError(error);
	let eventId: string | undefined;
	if (!duplicate && !context.expected) {
		try {
			eventId = Sentry.withScope((scope) => {
				for (const [key, value] of Object.entries(record.attributes)) {
					scope.setTag(key, String(value));
				}
				scope.setFingerprint([...record.fingerprint]);
				scope.setContext("mcp", {
					kind: context.kind,
					...record.attributes,
					...(record.responseError
						? { "hevy.api.response_error": record.responseError }
						: {}),
				});
				return Sentry.captureException(createSentryError(record));
			});
		} catch {
			// Sentry failures must never affect MCP behavior.
		}
	}

	if (span) {
		try {
			if (!duplicate && !context.expected) {
				span.recordException(record.exception);
				if (record.responseError) {
					span.addEvent("mcp.failure.detail", {
						"hevy.api.response_error": record.responseError,
					});
				}
			}
			setSpanAttributes(span, record.attributes);
			if (!context.expected) {
				span.setStatus({ code: SpanStatusCode.ERROR });
			}
			if (eventId) span.setAttribute("sentry.event_id", eventId);
		} catch {
			// OTel failures must never affect MCP behavior.
		}
	}

	return {
		...(diagnosticId ? { diagnosticId } : {}),
		...(eventId ? { eventId } : {}),
		...(traceContext.traceId ? { traceId: traceContext.traceId } : {}),
		...(traceContext.spanId ? { spanId: traceContext.spanId } : {}),
	};
}

