function sanitizeSentryTags(tags: ErrorEvent["tags"]): ErrorEvent["tags"] {
	if (!tags) return undefined;
	const output: NonNullable<ErrorEvent["tags"]> = {};
	for (const [key, value] of Object.entries(tags)) {
		if (!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))) continue;
		if (
			typeof value !== "string" &&
			typeof value !== "number" &&
			typeof value !== "boolean"
		) {
			continue;
		}
		output[truncate(key, 128)] =
			typeof value === "string"
				? sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH)
				: value;
	}
	return output;
}

export function sanitizeSentryBreadcrumbs(
	breadcrumbs: ErrorEvent["breadcrumbs"],
): ErrorEvent["breadcrumbs"] {
	if (!breadcrumbs) return undefined;
	const output: Breadcrumb[] = [];
	for (const breadcrumb of breadcrumbs.slice(-MAX_BREADCRUMBS)) {
		if (
			!breadcrumb ||
			typeof breadcrumb.category !== "string" ||
			!SAFE_BREADCRUMB_CATEGORY.test(breadcrumb.category)
		) {
			continue;
		}
		const message =
			typeof breadcrumb.message === "string"
				? sanitizeDiagnosticText(breadcrumb.message, MAX_MESSAGE_LENGTH)
				: undefined;
		const data = sanitizeBreadcrumbData(breadcrumb.data);
		if (!message && !data) continue;
		const safeBreadcrumb: Breadcrumb = {
			category: breadcrumb.category,
			...(message ? { message } : {}),
			...(typeof breadcrumb.level === "string" &&
			SAFE_BREADCRUMB_LEVELS.has(breadcrumb.level)
				? { level: breadcrumb.level as Breadcrumb["level"] }
				: {}),
			...(typeof breadcrumb.timestamp === "number" &&
			Number.isFinite(breadcrumb.timestamp)
				? { timestamp: breadcrumb.timestamp }
				: {}),
			...(data ? { data } : {}),
		};
		output.push(safeBreadcrumb);
	}
	return output.length > 0 ? output : undefined;
}

/** Add a privacy-filtered application breadcrumb without affecting MCP behavior. */
export function addSentryBreadcrumb(breadcrumb: Breadcrumb): void {
	if (!TELEMETRY_ENABLED) return;
	const safeBreadcrumb = sanitizeSentryBreadcrumbs([breadcrumb])?.[0];
	if (!safeBreadcrumb) return;
	try {
		Sentry.addBreadcrumb(safeBreadcrumb);
	} catch {
		// Breadcrumb failures must never affect MCP behavior.
	}
}

